from functools import lru_cache

def outcome(n, s, k):
    @lru_cache(None)
    def dp(i, k):
        if k == 0:
            return 1
        if i == 0 or k < 0:
            return 0
        return sum(dp(i-1, k-j) for j in range(1, s+1))

    return dp(n, k)

