def average_string(s):
    num_map = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9
    }
    if not s:
        return "n/a"
    total = 0
    count = 0
    for word in s.split():
        if word in num_map:
            total += num_map[word]
            count += 1
        else:
            return "n/a"
    if count == 0:
        return "n/a"
    avg = total // count
    return list(num_map.keys())[list(num_map.values()).index(avg)]
