def blocks(s):
    from collections import defaultdict, deque

    def get_next_block(blocks):
        block = []
        for char in s:
            if block and ord(char) < ord(block[-1]):
                break
            block.append(char)
        return ''.join(block)

    blocks = defaultdict(deque)
    result = []

    while s:
        block = get_next_block(s)
        blocks[len(block)].append(block)
        s = s[len(block):]

    for length in sorted(blocks.keys()):
        result.extend(blocks[length])

    return '-'.join(result)
